def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = [list(sorted_intervals[0])]

    for i in range(1, len(sorted_intervals)):
        start, end = sorted_intervals[i]
        last_start, last_end = merged[-1]

        if start <= last_end:
            merged[-1][1] = max(last_end, end)
        else:
            merged.append([start, end])

    return merged

import heapq
from collections import defaultdict


def toposort(nodes, edges):
    adj = defaultdict(set)
    in_degree = {node: 0 for node in nodes}

    for src, dst in edges:
        if dst not in adj[src]:
            adj[src].add(dst)
            in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    _KEY_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    env = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid line (missing '='): {line!r}")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not _KEY_RE.match(key):
            raise ValueError(f"Invalid key: {key!r}")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        env[key] = value
    return env

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    normalized = text.replace('\r\n', '\n')
    lines = normalized.split('\n')

    events = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    break
                events.append(data)
            data_lines = []
        elif line.startswith(':'):
            pass
        elif ':' in line:
            field, _, value = line.partition(':')
            if field == 'data':
                if value.startswith(' '):
                    value = value[1:]
                data_lines.append(value)
        # lines without a colon are ignored

    return events

import math


def retry_delay(attempt, base, cap):
    """Return min(cap, base * 2**attempt) as a float.

    Handles extremely large attempt values (e.g. 10**9) without
    constructing a huge integer or overflowing.
    """
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("attempt, base, and cap must be nonnegative")

    if base == 0 or cap == 0:
        return 0.0

    # Determine whether base * 2**attempt >= cap using logarithms,
    # avoiding any large-integer or float-overflow construction.
    log_result = math.log(base) + attempt * math.log(2.0)
    log_cap = math.log(cap)

    if log_result >= log_cap:
        return float(cap)

    # The product is strictly less than cap (a finite float), so it is
    # representable.  math.ldexp computes base * 2**attempt directly
    # in the exponent domain without materialising 2**attempt.
    return math.ldexp(base, attempt)

def fifo_admit(active, queued, budget, slots):
    for r in queued:
        if r > budget:
            raise ValueError(f"Reservation {r} exceeds budget {budget}")

    remaining_slots = slots - len(active)
    remaining_tokens = budget - sum(active)

    admitted = []
    remaining = []

    for i, r in enumerate(queued):
        if len(admitted) < remaining_slots and r <= remaining_tokens:
            admitted.append(r)
            remaining_tokens -= r
        else:
            remaining = list(queued[i:])
            break

    return admitted, remaining
